const roleSections = {
  'safety officer': ['executive-summary', 'risk-overview', 'affected-zones', 'sensor-statistics', 'major-alerts', 'ai-predictions', 'node-health', 'trend-analysis', 'recommended-actions'],
  'dgms inspector': ['executive-summary', 'risk-overview', 'affected-zones', 'sensor-statistics', 'major-alerts', 'ai-predictions', 'node-health', 'trend-analysis', 'recommended-actions'],
  'geotech engineer': ['executive-summary', 'risk-overview', 'sensor-statistics', 'ai-predictions', 'trend-analysis'],
  'mine manager': ['executive-summary', 'risk-overview', 'affected-zones', 'major-alerts', 'recommended-actions']
};

const labels = {
  'executive-summary': 'Executive Summary',
  'risk-overview': 'Risk Overview',
  'affected-zones': 'Affected Zones',
  'sensor-statistics': 'Sensor Statistics',
  'major-alerts': 'Major Alerts',
  'ai-predictions': 'AI Predictions',
  'node-health': 'Node Health',
  'trend-analysis': 'Trend Analysis',
  'recommended-actions': 'Recommended Actions'
};

const reportDate = $now.setZone('Asia/Kolkata');
const start = reportDate.startOf('day').toUTC().toISO();
const end = reportDate.endOf('day').toUTC().toISO();

return $input.all()
  .map(({ json: row }) => {
    const email = String(row.Email ?? row.email ?? '').trim();
    const role = String(row.Roles ?? row.Role ?? row.role ?? '').trim();
    const roleKey = role.toLowerCase();
    const sectionIds = roleSections[roleKey] ?? ['executive-summary', 'risk-overview', 'major-alerts'];

    if (!email) return null;

    return {
      json: {
        recipientId: row.ID ?? row.id ?? '',
        email,
        phone: row['Phone No'] ?? row.phone ?? '',
        role: role || 'Other',
        reportConfig: {
          mine: 'Prototype Mine',
          date_range: { start, end },
          node_scope: ['ALL'],
          region: '',
          sections: sectionIds.map((id) => ({ id, label: labels[id] ?? id, enabled: true }))
        }
      }
    };
  })
  .filter(Boolean);

return $input.all().map((item) => {
  const recipient = $('Map Role And Sections').item.json;
  return {
    json: {
      ...recipient,
      report: item.json,
      summary: item.json.summary ?? '',
      riskOverview: item.json.risk_overview ?? {},
      reportConfig: recipient.reportConfig
    }
  };
});
